#!/usr/bin/env node
/**
 * tred-guide.mjs — le guide du premier lancement (web + mobile),
 * et tout ce qui a été construit depuis ton dernier push.
 *
 * Ce script REMPLACE des fichiers. Il ne fusionne rien : ce qu'il pose est
 * exactement l'arbre que j'ai compilé et testé de mon côté (tsc 0, tests
 * 106/106, vite build, expo export). Aucune surprise possible entre ce qui a
 * été vérifié et ce qui arrive chez toi.
 *
 *   node tred-guide.mjs
 *
 * Il se trouve tout seul : peu importe le dossier d'où tu le lances.
 */
import { readFileSync, writeFileSync, mkdirSync, existsSync, rmSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { gunzipSync, inflateSync } from "node:zlib";

/** Remonte jusqu'au dossier qui contient `packages/web`, depuis DEUX points de
 *  départ : le dossier courant et l'endroit où ce fichier est posé. C'est ce
 *  qui a manqué la fois où tu l'avais lancé depuis Downloads. */
function racine() {
  const departs = [process.cwd(), dirname(fileURLToPath(import.meta.url))];
  for (const depart of departs) {
    let d = resolve(depart);
    for (let i = 0; i < 8; i++) {
      if (existsSync(join(d, "packages", "web", "package.json"))) return d;
      const parent = dirname(d);
      if (parent === d) break;
      d = parent;
    }
  }
  return null;
}

const R = racine();
if (!R) {
  console.error("Dépôt introuvable. Lance ce fichier depuis C:\\dev\\tred-rdm\\aerostudy-ai,");
  console.error("ou pose-le dedans et relance.");
  process.exit(1);
}
console.log("Dépôt :", R, "\n");

const PAYLOAD = "";

const LOT = JSON.parse(inflateSync(Buffer.from(PAYLOAD, "base64")).toString("utf8"));

let ecrits = 0;
for (const [chemin, b64] of Object.entries(LOT.ecrire)) {
  const cible = join(R, chemin);
  mkdirSync(dirname(cible), { recursive: true });
  writeFileSync(cible, Buffer.from(b64, "base64"));
  ecrits++;
  console.log("  écrit   ", chemin);
}

for (const chemin of LOT.supprimer) {
  const cible = join(R, chemin);
  if (existsSync(cible)) {
    rmSync(cible);
    console.log("  supprimé", chemin);
  }
}

console.log(`\n${ecrits} fichiers posés.\n`);
console.log("Ensuite, dans ce dossier :");
console.log("  node node_modules/typescript/bin/tsc --noEmit -p packages/web");
console.log("  node node_modules/.bin/vite build --config packages/web/vite.config.ts");
console.log("\nPuis la base (elle n'a jamais tourné) :");
console.log("  node migre-base.mjs");
console.log("\nPuis l'envoi :");
console.log("  git add -A && git commit -m \"guide de premier lancement, Faecher, relance du soir, garde-fou du tuteur\" && git push");
